function renderInteractionTools(){const s=current(),fill=(id,objects)=>{const e=$(id),old=e.value;e.replaceChildren();for(const o of objects){const option=document.createElement('option');option.value=o.id;option.textContent=o.name;e.append(option)}if(objects.some(o=>o.id===old))e.value=old};fill('interactionActor',storyActors(s));fill('interactionOther',storyActors(s));fill('interactionProp',s.objects.filter(o=>!isAnimatedCharacter(o)&&o.type!=='text'));$('interactionReceiverFields').hidden=$('interactionKind').value!=='handover';$('propInteractionTime').max=s.duration;$('propInteractionTime').value=time;const list=$('propInteractionList');list.replaceChildren();for(const i of s.propInteractions||[]){const row=document.createElement('div');row.className='production-entry';const text=document.createElement('span');text.textContent=(s.objects.find(o=>o.id===i.propId)?.name||'Object')+' · '+propInteractionKinds[i.kind]+' · '+i.start.toFixed(1)+'s';const seek=storyButton('Preview',()=>{time=Math.min(s.duration,i.start+i.duration*.7);paintInteractionPreview()});const del=storyButton('Remove',()=>{if([i.actorId,i.propId,i.otherId].some(id=>s.objects.find(o=>o.id===id)?.locked))return toast('Unlock the affected layers first.');s.propInteractions=s.propInteractions.filter(e=>e!==i);save();render();renderInteractionTools()});row.append(text,seek,del);list.append(row)}paintInteractionPreview()}
