async function openPropInteractions(){stop();renderInteractionTools();$('interactionStart').value=+time.toFixed(2);$('interactionDuration').value=Math.min(1.2,Math.max(.2,current().duration-time)).toFixed(1);if(isAnimatedCharacter(object()))$('interactionActor').value=object().id;else if(object())$('interactionProp').value=object().id;const prop=current().objects.find(o=>o.id===$('interactionProp').value);if(prop)$('interactionScale').value=stateAt(prop,time).scale;$('propInteractionsDialog').showModal();const s=current();await preloadProductionAssets(s);if(current()===s&&$('propInteractionsDialog').open)paintInteractionPreview()}
