$('addPropInteraction').onclick=()=>{try{addPropInteraction({kind:$('interactionKind').value,actorId:$('interactionActor').value,propId:$('interactionProp').value,otherId:$('interactionOther').value,hand:$('interactionHand').value,otherHand:$('interactionOtherHand').value,start:+$('interactionStart').value,duration:+$('interactionDuration').value,offset:{x:+$('interactionOffsetX').value,y:+$('interactionOffsetY').value},rotation:+$('interactionRotation').value,scale:+$('interactionScale').value,followRotation:$('interactionFollowRotation').checked});renderInteractionTools();$('propInteractionStatus').textContent='Interaction added. Scrub or play to review it.'}catch(e){$('propInteractionStatus').textContent=e.message}};$('releaseSelectedProp').onclick=()=>{try{const p=current().objects.find(o=>o.id===$('interactionProp').value);if(!p)throw Error('Choose an object.');releaseProp(p);renderInteractionTools()}catch(e){$('propInteractionStatus').textContent=e.message}};
const controlsBeforePropInteractions=renderControls;renderControls=function(){controlsBeforePropInteractions();const o=object();if(!o)return;const b=storyButton('Characters & objects',openPropInteractions);b.id='openPropInteractions';b.disabled=!!o.locked;if(isAnimatedCharacter(o))$('walkCharacterTo')?.closest('details')?.append(b);else if(o.type!=='text')$('controls').prepend(b)};
