const remapBeforeInteractions=remapStoryReferences;remapStoryReferences=function(copy,objects,audio,scenes){remapBeforeInteractions(copy,objects,audio,scenes);for(const s of copy.scenes)for(const i of s.propInteractions||[]){i.id=uid();for(const field of ['actorId','propId','otherId'])if(i[field])i[field]=objects.get(i[field])||i[field]}};
const durationBeforeInteractions=changeSceneDuration;changeSceneDuration=function(s,n){if((s.propInteractions||[]).some(i=>i.start+i.duration>+n+.001))return toast('Move or trim object interactions before shortening this scene.'),false;return durationBeforeInteractions(s,n)};
