const validateBeforeInteractions=valid;valid=function(p){try{return validateBeforeInteractions(p)&&p.scenes.every(s=>!s.propInteractions||Array.isArray(s.propInteractions)&&s.propInteractions.length<=200&&s.propInteractions.every(i=>i&&typeof i.id==='string'&&Object.hasOwn(propInteractionKinds,i.kind)&&['actorId','propId'].every(k=>typeof i[k]==='string')&&(i.otherId===null||typeof i.otherId==='string')&&['left','right'].includes(i.hand)&&['left','right'].includes(i.otherHand)&&Number.isFinite(i.start)&&i.start>=0&&Number.isFinite(i.duration)&&i.duration>=.2&&i.start+i.duration<=s.duration+.001&&i.offset&&['x','y'].every(k=>Number.isFinite(i.offset[k])&&Math.abs(i.offset[k])<=200)&&Number.isFinite(i.rotation)&&Math.abs(i.rotation)<=360&&Number.isFinite(i.scale)&&i.scale>=.05&&i.scale<=10&&typeof i.followRotation==='boolean'&&i.fromPose&&Object.keys(pose).every(k=>Number.isFinite(i.fromPose[k]))&&(!i.actorStartPose||Object.keys(pose).every(k=>Number.isFinite(i.actorStartPose[k])))&&(!i.otherStartPose||Object.keys(pose).every(k=>Number.isFinite(i.otherStartPose[k])))))}catch{return false}};
